import 'package:flutter/material.dart';

import 'package:bh_finder/core/theme/app_colors.dart';
import 'package:bh_finder/core/theme/app_radius.dart';
import 'package:bh_finder/core/theme/app_spacing.dart';
import 'package:bh_finder/core/theme/app_text_styles.dart';

import 'package:bh_finder/shared/widgets/others/section_title.dart';

//============================================================================
//! ADD PROPERTY AUTO GENERATED SECTION
//============================================================================

class AddPropertyAutoGeneratedSection extends StatelessWidget {
  //============================================================================
  //! CONSTRUCTOR
  //============================================================================

  const AddPropertyAutoGeneratedSection({super.key});

  //============================================================================
  //! BUILD
  //============================================================================

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: const [
        //==============================================================
        //! TITLE
        //==============================================================
        SectionTitle(title: 'Auto Generated'),

        SizedBox(height: AppSpacing.md),

        _AutoGeneratedCard(title: 'Minimum Price', value: '₱2,500 / month'),

        SizedBox(height: AppSpacing.md),

        _AutoGeneratedCard(title: 'Distance to Campus', value: '0.8 km'),
      ],
    );
  }
}

//============================================================================
//! AUTO GENERATED CARD
//============================================================================

class _AutoGeneratedCard extends StatelessWidget {
  //============================================================================
  //! CONSTRUCTOR
  //============================================================================

  const _AutoGeneratedCard({required this.title, required this.value});

  //============================================================================
  //! PROPERTIES
  //============================================================================

  final String title;

  final String value;

  //============================================================================
  //! BUILD
  //============================================================================

  @override
  Widget build(BuildContext context) {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(AppSpacing.md),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(AppRadius.md),
        border: Border.all(color: AppColors.tertiary, width: 0.5),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            title,
            style: AppTextStyles.bodyMedium.copyWith(
              color: AppColors.secondary,
            ),
          ),

          const SizedBox(height: AppSpacing.xs),

          Text(
            value,
            style: AppTextStyles.bodyMedium.copyWith(
              fontWeight: FontWeight.bold,
              color: AppColors.primary,
            ),
          ),
        ],
      ),
    );
  }
}
